export const ไม่นับ = [
  { รูป: /\/tests?\//, เหตุ: 'เทส — ชื่อของที่ทดสอบอยู่ในตัวเทส' },
  { รูป: /fixtures?/, เหตุ: 'ฟิกซ์เจอร์' },
]
export const ไม่นับไฟล์นี้ = (พาธ) => ไม่นับ.some((x) => x.รูป.test(String(พาธ ?? '')))
export const เหตุที่ไม่นับ = (พาธ) => ไม่นับ.find((x) => x.รูป.test(String(พาธ ?? '')))?.เหตุ ?? null
